use clap::{builder::PossibleValue, value_parser, Arg, ArgAction, Command};
use std::path::PathBuf;

pub const SHELLS: &[(&str, &str)] = &[
    ("bash", "Bourne Again `SHell` (bash)"),
    ("elvish", "Elvish shell"),
    ("fish", "Friendly Interactive `SHell` (fish)"),
    ("powershell", "`PowerShell`"),
    ("zsh", "Z `SHell` (zsh)"),
    ("nushell", "Nushell"),
];

pub fn build() -> Command {
    let check = Command::new("check")
        .about("Check availability")
        .arg(
            Arg::new("path")
                .value_name("path")
                .help("The path of a file or directory to check availability")
                .value_parser(value_parser!(PathBuf))
                .required(false),
        )
        .arg(
            Arg::new("all_targets")
                .long("all-targets")
                .help("Run the check for all targets instead of current only")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("all_features")
                .long("all-features")
                .help("Run the check for all features instead of the current active ones only")
                .action(ArgAction::SetTrue),
        );

    let clean = Command::new("clean").about("Remove artifacts from the target directory");

    let install = Command::new("install")
        .about("Install the toolchain")
        .arg(
            Arg::new("path")
                .long("path")
                .value_name("path")
                .help("Runtime directory path to install RustOwl toolchain")
                .value_parser(value_parser!(PathBuf))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("skip_rustowl_toolchain")
                .long("skip-rustowl-toolchain")
                .help("Install Rust toolchain only")
                .action(ArgAction::SetTrue),
        );
    let uninstall = Command::new("uninstall").about("Uninstall the toolchain");
    let toolchain = Command::new("toolchain")
        .about("Install or uninstall the toolchain")
        .subcommand(install)
        .subcommand(uninstall);

    let shells: Vec<PossibleValue> = SHELLS
        .iter()
        .map(|(n, h)| PossibleValue::new(*n).help(*h))
        .collect();
    let completions = Command::new("completions")
        .about("Generate shell completions")
        .arg(
            Arg::new("shell")
                .value_name("SHELL")
                .help("The shell to generate completions for")
                .required(true)
                .value_parser(clap::builder::PossibleValuesParser::new(shells))
                .action(ArgAction::Set),
        );

    Command::new("rustowl")
        .version("1.0.0-rc.1")
        .disable_version_flag(true)
        .arg(
            Arg::new("version")
                .short('V')
                .long("version")
                .help("Print version")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("quiet")
                .short('q')
                .long("quiet")
                .help("Suppress output")
                .action(ArgAction::Count),
        )
        .arg(
            Arg::new("stdio")
                .long("stdio")
                .help("Use stdio to communicate with the LSP server")
                .action(ArgAction::SetTrue),
        )
        .subcommand(check)
        .subcommand(clean)
        .subcommand(toolchain)
        .subcommand(completions)
}
EOF
