{"command":"cd /workspace && cat > src/nushell.rs <<'EOF'
//! Nushell completion script generator.

use clap::builder::ValueHint;
use clap::{Arg, Command};

pub fn generate(cmd: &mut Command, bin_name: &str) -> String {
    cmd.set_bin_name(bin_name);
    cmd.build();
    let mut out = String::from("module completions {\n\n");
    emit_command(cmd, bin_name, &mut out);
    out.push_str("}\n\nexport use completions *\n");
    out
}

fn quoted_name(name: &str) -> String {
    if name.contains(' ') {
        format!("\"{name}\"")
    } else {
        name.to_string()
    }
}

fn first_line(s: &str) -> String {
    s.lines().next().unwrap_or("").to_string()
}

fn value_type(arg: &Arg) -> &'static str {
    match arg.get_value_hint() {
        ValueHint::AnyPath | ValueHint::FilePath | ValueHint::DirPath | ValueHint::ExecutablePath => {
            "path"
        }
        _ => "string",
    }
}

fn has_values(arg: &Arg) -> bool {
    arg.get_num_args().map(|r| r.takes_values()).unwrap_or(false)
}

fn emit_command(cmd: &Command, full_name: &str, out: &mut String) {
    let visible_pv = |arg: &Arg| -> Vec<String> {
        arg.get_possible_values()
            .iter()
            .filter(|v| !v.is_hide_set())
            .map(|v| v.get_name().to_string())
            .collect()
    };

    // value completer definitions
    for arg in cmd.get_arguments().filter(|a| !a.is_hide_set()) {
        let pvs = visible_pv(arg);
        if !pvs.is_empty() && has_values(arg) {
            out.push_str(&format!(
                "  def \"nu-complete {} {}\" [] {{\n    [ {} ]\n  }}\n\n",
                full_name,
                arg.get_id(),
                pvs.iter()
                    .map(|v| format!("\"{v}\""))
                    .collect::<Vec<_>>()
                    .join(" ")
            ));
        }
    }

    if let Some(about) = cmd.get_about() {
        out.push_str(&format!("  # {}\n", first_line(&about.to_string())));
    }
    out.push_str(&format!("  export extern {} [\n", quoted_name(full_name)));

    let mut lines = Vec::new();
    for arg in cmd
        .get_arguments()
        .filter(|a| !a.is_hide_set() && !a.is_positional())
    {
        let mut s = String::from("    ");
        if let Some(long) = arg.get_long() {
            s.push_str(&format!("--{long}"));
            if let Some(short) = arg.get_short() {
                s.push_str(&format!("(-{short})"));
            }
        } else if let Some(short) = arg.get_short() {
            s.push_str(&format!("-{short}"));
        }
        if has_values(arg) {
            let pvs = visible_pv(arg);
            if !pvs.is_empty() {
                s.push_str(&format!(
                    ": string@\"nu-complete {} {}\"",
                    full_name,
                    arg.get_id()
                ));
            } else {
                s.push_str(&format!(": {}", value_type(arg)));
            }
        }
        push_help(arg, &mut s);
        lines.push(s);
    }
    for arg in cmd.get_positionals().filter(|a| !a.is_hide_set()) {
        let mut s = String::from("    ");
        if arg.is_last_set() || matches!(arg.get_num_args(), Some(r) if r.max_values() > 1) {
            s.push_str("...");
        }
        s.push_str(&arg.get_id().to_string());
        if !arg.is_required_set() {
            s.push('?');
        }
        let pvs = visible_pv(arg);
        if !pvs.is_empty() {
            s.push_str(&format!(
                ": string@\"nu-complete {} {}\"",
                full_name,
                arg.get_id()
            ));
        } else {
            s.push_str(&format!(": {}", value_type(arg)));
        }
        push_help(arg, &mut s);
        lines.push(s);
    }
    for l in lines {
        out.push_str(&l);
        out.push('\n');
    }
    out.push_str("  ]\n\n");

    for sub in cmd.get_subcommands().filter(|s| !s.is_hide_set()) {
        let name = format!("{} {}", full_name, sub.get_name());
        emit_command(sub, &name, out);
    }
}

fn push_help(arg: &Arg, s: &mut String) {
    if let Some(help) = arg.get_help() {
        let indent: usize = 30;
        let width = indent.saturating_sub(s.len());
        s.push_str(&format!("{:>width$}# {}", ' ', first_line(&help.to_string())));
    }
}
EOF
