//! Minimal logger producing `<timestamp> <LEVEL> [<target>] <message>` lines on stderr.

use std::io::{IsTerminal, Write};
use std::sync::atomic::{AtomicU8, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
#[repr(u8)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

static MAX_LEVEL: AtomicU8 = AtomicU8::new(3);
static COLORS: AtomicU8 = AtomicU8::new(0);

/// Initialize the logger. `default` is the level filter used when `RUST_LOG`
/// does not contain a valid level name. 0 means "off".
pub fn init(default: u8) {
    let mut level = default;
    if let Ok(v) = std::env::var("RUST_LOG") {
        let v = v.to_ascii_lowercase();
        level = match v.as_str() {
            "off" => 0,
            "error" => 1,
            "warn" => 2,
            "info" => 3,
            "debug" => 4,
            "trace" => 5,
            _ => default,
        };
    }
    MAX_LEVEL.store(level, Ordering::SeqCst);
    if std::io::stderr().is_terminal() {
        COLORS.store(1, Ordering::SeqCst);
    }
}

pub fn max_level() -> u8 {
    MAX_LEVEL.load(Ordering::SeqCst)
}

pub fn enabled(level: Level) -> bool {
    (level as u8) <= max_level()
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub fn timestamp() -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    let secs = now.as_secs() as i64;
    let millis = now.subsec_millis();
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:03}Z",
        y,
        m,
        d,
        rem / 3600,
        (rem % 3600) / 60,
        rem % 60,
        millis
    )
}

pub fn log(level: Level, target: &str, msg: &str) {
    if !enabled(level) {
        return;
    }
    let name = match level {
        Level::Error => "ERROR",
        Level::Warn => "WARN ",
        Level::Info => "INFO ",
        Level::Debug => "DEBUG",
        Level::Trace => "TRACE",
    };
    let level_str = if COLORS.load(Ordering::SeqCst) == 1 {
        match level {
            Level::Error => format!("\x1b[31m{name}\x1b[0m"),
            Level::Warn => format!("\x1b[33m{name}\x1b[0m"),
            Level::Info => format!("\x1b[36m{name}\x1b[0m"),
            Level::Debug => format!("\x1b[35m{name}\x1b[0m"),
            Level::Trace => name.to_string(),
        }
    } else {
        name.to_string()
    };
    let line = format!("{} {} [{}] {}\n", timestamp(), level_str, target, msg);
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(line.as_bytes());
    let _ = lock.flush();
}

#[macro_export]
macro_rules! log_error {
    ($target:expr, $($arg:tt)*) => { $crate::log::log($crate::log::Level::Error, $target, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_warn {
    ($target:expr, $($arg:tt)*) => { $crate::log::log($crate::log::Level::Warn, $target, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_info {
    ($target:expr, $($arg:tt)*) => { $crate::log::log($crate::log::Level::Info, $target, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_debug {
    ($target:expr, $($arg:tt)*) => { $crate::log::log($crate::log::Level::Debug, $target, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_trace {
    ($target:expr, $($arg:tt)*) => { $crate::log::log($crate::log::Level::Trace, $target, &format!($($arg)*)) };
}

/// Emulates the message printed by the Rust runtime when a thread panics.
pub fn panic_message(thread: &str, location: &str, msg: &str) {
    use std::sync::atomic::AtomicBool;
    static FIRST: AtomicBool = AtomicBool::new(true);
    let mut s = format!("\nthread '{thread}' panicked at {location}:\n{msg}\n");
    if FIRST.swap(false, Ordering::SeqCst) {
        s.push_str("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n");
    }
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(s.as_bytes());
    let _ = lock.flush();
}
