//! Range arithmetic and MIR traversal helpers.

use crate::models::*;

pub fn is_super_range(r1: Range, r2: Range) -> bool {
    (r1.from() < r2.from() && r2.until() <= r1.until())
        || (r1.from() <= r2.from() && r2.until() < r1.until())
}

pub fn common_range(r1: Range, r2: Range) -> Option<Range> {
    if r2.from() < r1.from() {
        return common_range(r2, r1);
    }
    if r1.until() < r2.from() {
        return None;
    }
    let from = r2.from();
    let until = r1.until().min(r2.until());
    Range::new(from, until)
}

pub fn common_ranges(ranges: &[Range]) -> Vec<Range> {
    let mut out = Vec::new();
    for i in 0..ranges.len() {
        for j in (i + 1)..ranges.len() {
            if let Some(c) = common_range(ranges[i], ranges[j]) {
                out.push(c);
            }
        }
    }
    eliminated_ranges(out)
}

pub fn merge_ranges(r1: Range, r2: Range) -> Option<Range> {
    if common_range(r1, r2).is_some() || r1.until() == r2.from() || r2.until() == r1.from() {
        let from = r1.from().min(r2.from());
        let until = r1.until().max(r2.until());
        Range::new(from, until)
    } else {
        None
    }
}

pub fn eliminated_ranges(mut ranges: Vec<Range>) -> Vec<Range> {
    let mut i = 0;
    'outer: while i < ranges.len() {
        let mut j = 0;
        while j < ranges.len() {
            if i != j {
                if let Some(merged) = merge_ranges(ranges[i], ranges[j]) {
                    ranges[i] = merged;
                    ranges.remove(j);
                    continue 'outer;
                }
            }
            j += 1;
        }
        i += 1;
    }
    ranges
}

pub fn exclude_ranges(mut from: Vec<Range>, excludes: Vec<Range>) -> Vec<Range> {
    let mut i = 0;
    'outer: while i < from.len() {
        let mut j = 0;
        while j < excludes.len() {
            if let Some(common) = common_range(from[i], excludes[j]) {
                if let Some(r) = Range::new(from[i].from(), common.from().add(-1)) {
                    from.push(r);
                }
                if let Some(r) = Range::new(common.until().add(1), from[i].until()) {
                    from.push(r);
                }
                from.remove(i);
                continue 'outer;
            }
            j += 1;
        }
        i += 1;
    }
    eliminated_ranges(from)
}

pub trait MirVisitor {
    fn visit_func(&mut self, _func: &Function) {}
    fn visit_decl(&mut self, _decl: &MirDecl) {}
    fn visit_stmt(&mut self, _stmt: &MirStatement) {}
    fn visit_term(&mut self, _term: &MirTerminator) {}
}

pub fn mir_visit(func: &Function, visitor: &mut impl MirVisitor) {
    visitor.visit_func(func);
    for decl in &func.decls {
        visitor.visit_decl(decl);
    }
    for bb in &func.basic_blocks {
        for stmt in &bb.statements {
            visitor.visit_stmt(stmt);
        }
        if let Some(term) = &bb.terminator {
            visitor.visit_term(term);
        }
    }
}

/// Convert a character index into a (line, character) pair.
pub fn index_to_line_char(s: &str, idx: Loc) -> (u32, u32) {
    let mut line = 0u32;
    let mut col = 0u32;
    for (i, c) in s.chars().filter(|c| *c != '\r').enumerate() {
        if idx == Loc(i as u32) {
            return (line, col);
        }
        if c == '\n' {
            line += 1;
            col = 0;
        } else {
            col += 1;
        }
    }
    (0, 0)
}

/// Convert a (line, character) pair into a character index.
pub fn line_char_to_index(s: &str, mut line: u32, char: u32) -> u32 {
    let mut col = 0u32;
    for (i, c) in s.chars().filter(|c| *c != '\r').enumerate() {
        if line == 0 && col == char {
            return i as u32;
        }
        if c == '\n' && 0 < line {
            line -= 1;
            col = 0;
        } else {
            col += 1;
        }
    }
    0
}
