//! Computation of the decorations shown for the variable under the cursor.

use crate::models::*;
use crate::utils::{self, MirVisitor};
use serde_json::{json, Value};
use std::collections::HashSet;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DecoKind {
    Lifetime,
    ImmBorrow,
    MutBorrow,
    Move,
    Call,
    SharedMut,
    Outlive,
}

impl DecoKind {
    fn order(self) -> u8 {
        match self {
            DecoKind::Lifetime => 0,
            DecoKind::ImmBorrow => 1,
            DecoKind::MutBorrow => 2,
            DecoKind::Move => 3,
            DecoKind::Call => 4,
            DecoKind::SharedMut => 5,
            DecoKind::Outlive => 6,
        }
    }
    fn name(self) -> &'static str {
        match self {
            DecoKind::Lifetime => "lifetime",
            DecoKind::ImmBorrow => "imm_borrow",
            DecoKind::MutBorrow => "mut_borrow",
            DecoKind::Move => "move",
            DecoKind::Call => "call",
            DecoKind::SharedMut => "shared_mut",
            DecoKind::Outlive => "outlive",
        }
    }
}

#[derive(Clone, Debug)]
pub struct Deco {
    pub kind: DecoKind,
    pub local: FnLocal,
    pub range: Range,
    pub hover_text: String,
    pub overlapped: bool,
}

impl Deco {
    pub fn to_lsp_value(&self, text: &str) -> Value {
        let start = utils::index_to_line_char(text, self.range.from());
        let end = utils::index_to_line_char(text, self.range.until());
        json!({
            "type": self.kind.name(),
            "local": {"id": self.local.id, "fn_id": self.local.fn_id},
            "range": {
                "start": {"line": start.0, "character": start.1},
                "end": {"line": end.0, "character": end.1},
            },
            "hover_text": self.hover_text,
            "overlapped": self.overlapped,
        })
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SelectReason {
    Var,
    Move,
    Borrow,
    Call,
}

pub struct SelectLocal {
    pos: Loc,
    candidate_local_decls: Vec<FnLocal>,
    selected: Option<(SelectReason, FnLocal, Range)>,
}

impl SelectLocal {
    pub fn new(pos: Loc) -> Self {
        Self {
            pos,
            candidate_local_decls: Vec::new(),
            selected: None,
        }
    }

    fn select(&mut self, reason: SelectReason, local: FnLocal, range: Range) {
        if !self.candidate_local_decls.contains(&local) {
            return;
        }
        if range.from() <= self.pos && self.pos <= range.until() {
            if let Some((old_reason, _, old_range)) = self.selected {
                match (old_reason, reason) {
                    (_, SelectReason::Var) => {
                        if range.size() < old_range.size() {
                            self.selected = Some((reason, local, range));
                        }
                    }
                    (SelectReason::Var, _) => {}
                    (_, SelectReason::Move) | (_, SelectReason::Borrow) => {
                        if range.size() < old_range.size() {
                            self.selected = Some((reason, local, range));
                        }
                    }
                    (SelectReason::Call, SelectReason::Call) => {
                        if old_range.size() < range.size() {
                            self.selected = Some((reason, local, range));
                        }
                    }
                    _ => {}
                }
            } else {
                self.selected = Some((reason, local, range));
            }
        }
    }

    pub fn selected(&self) -> Option<FnLocal> {
        self.selected.map(|v| v.1)
    }
}

impl MirVisitor for SelectLocal {
    fn visit_decl(&mut self, decl: &MirDecl) {
        let local = match decl {
            MirDecl::User { local, .. } => *local,
            MirDecl::Other { local, .. } => *local,
        };
        self.candidate_local_decls.push(local);
        if let MirDecl::User { local, span, .. } = decl {
            self.select(SelectReason::Var, *local, *span);
        }
    }
    fn visit_stmt(&mut self, stmt: &MirStatement) {
        if let MirStatement::Assign { rval, .. } = stmt {
            match rval {
                Some(MirRval::Move {
                    target_local,
                    range,
                }) => self.select(SelectReason::Move, *target_local, *range),
                Some(MirRval::Borrow {
                    target_local,
                    range,
                    ..
                }) => self.select(SelectReason::Borrow, *target_local, *range),
                _ => {}
            }
        }
    }
    fn visit_term(&mut self, term: &MirTerminator) {
        if let MirTerminator::Call {
            destination_local,
            fn_span,
        } = term
        {
            self.select(SelectReason::Call, *destination_local, *fn_span);
        }
    }
}

pub struct CalcDecos {
    locals: HashSet<FnLocal>,
    decorations: Vec<Deco>,
}

impl CalcDecos {
    pub fn new(locals: impl IntoIterator<Item = FnLocal>) -> Self {
        Self {
            locals: locals.into_iter().collect(),
            decorations: Vec::new(),
        }
    }

    fn sort_by_definition(&mut self) {
        self.decorations.sort_by_key(|d| d.kind.order());
    }

    pub fn handle_overlapping(&mut self) {
        self.sort_by_definition();
        let mut i = 1;
        while i < self.decorations.len() {
            let current_range = self.decorations[i].range;
            let mut j = 0;
            while j < i {
                let prev = self.decorations[j].clone();
                if let Some(common) = utils::common_range(current_range, prev.range) {
                    let non_overlapping = utils::exclude_ranges(vec![prev.range], vec![common]);
                    self.decorations[j].range = common;
                    self.decorations[j].overlapped = true;
                    for (k, range) in non_overlapping.into_iter().enumerate() {
                        let mut d = prev.clone();
                        d.range = range;
                        d.overlapped = false;
                        self.decorations.insert(j + k + 1, d);
                        i += 1;
                    }
                }
                j += 1;
            }
            i += 1;
        }
    }

    pub fn decorations(self) -> Vec<Deco> {
        self.decorations
    }
}

impl MirVisitor for CalcDecos {
    fn visit_decl(&mut self, decl: &MirDecl) {
        let (local, lives, shared_borrow, mutable_borrow, drop_range, must_live_at, name, drop) =
            match decl {
                MirDecl::User {
                    local,
                    name,
                    lives,
                    shared_borrow,
                    mutable_borrow,
                    drop_range,
                    must_live_at,
                    drop,
                    ..
                } => (
                    *local,
                    lives,
                    shared_borrow,
                    mutable_borrow,
                    drop_range,
                    must_live_at,
                    Some(name),
                    *drop,
                ),
                MirDecl::Other {
                    local,
                    lives,
                    shared_borrow,
                    mutable_borrow,
                    drop_range,
                    must_live_at,
                    drop,
                    ..
                } => (
                    *local,
                    lives,
                    shared_borrow,
                    mutable_borrow,
                    drop_range,
                    must_live_at,
                    None,
                    *drop,
                ),
            };
        if !self.locals.contains(&local) {
            return;
        }
        let var_str = name
            .map(|v| format!("variable `{v}`"))
            .unwrap_or_else(|| "anonymus variable".to_owned());
        let lives = utils::eliminated_ranges(lives.clone());
        let drop_copy_live = if drop {
            utils::eliminated_ranges(drop_range.clone())
        } else {
            lives.clone()
        };
        for range in &drop_copy_live {
            self.decorations.push(Deco {
                kind: DecoKind::Lifetime,
                local,
                range: *range,
                hover_text: format!("lifetime of {var_str}"),
                overlapped: false,
            });
        }
        let mut borrows = shared_borrow.clone();
        borrows.extend_from_slice(mutable_borrow);
        let shared_mut = utils::common_ranges(&borrows);
        for range in shared_mut {
            self.decorations.push(Deco {
                kind: DecoKind::SharedMut,
                local,
                range,
                hover_text: format!("immutable and mutable borrows of {var_str} exist here"),
                overlapped: false,
            });
        }
        let outlive = utils::exclude_ranges(must_live_at.clone(), drop_copy_live);
        for range in outlive {
            self.decorations.push(Deco {
                kind: DecoKind::Outlive,
                local,
                range,
                hover_text: format!("{var_str} is required to live here"),
                overlapped: false,
            });
        }
    }

    fn visit_stmt(&mut self, stmt: &MirStatement) {
        if let MirStatement::Assign { rval, .. } = stmt {
            match rval {
                Some(MirRval::Move {
                    target_local,
                    range,
                }) => {
                    if self.locals.contains(target_local) {
                        self.decorations.push(Deco {
                            kind: DecoKind::Move,
                            local: *target_local,
                            range: *range,
                            hover_text: "variable moved".to_string(),
                            overlapped: false,
                        });
                    }
                }
                Some(MirRval::Borrow {
                    target_local,
                    range,
                    mutable,
                    ..
                }) => {
                    if self.locals.contains(target_local) {
                        if *mutable {
                            self.decorations.push(Deco {
                                kind: DecoKind::MutBorrow,
                                local: *target_local,
                                range: *range,
                                hover_text: "mutable borrow".to_string(),
                                overlapped: false,
                            });
                        } else {
                            self.decorations.push(Deco {
                                kind: DecoKind::ImmBorrow,
                                local: *target_local,
                                range: *range,
                                hover_text: "immutable borrow".to_string(),
                                overlapped: false,
                            });
                        }
                    }
                }
                _ => {}
            }
        }
    }

    fn visit_term(&mut self, term: &MirTerminator) {
        if let MirTerminator::Call {
            destination_local,
            fn_span,
        } = term
        {
            if self.locals.contains(destination_local) {
                for deco in &self.decorations {
                    if deco.kind == DecoKind::Call && utils::is_super_range(*fn_span, deco.range) {
                        return;
                    }
                }
                let mut i = 0;
                while i < self.decorations.len() {
                    if self.decorations[i].kind == DecoKind::Call
                        && utils::is_super_range(self.decorations[i].range, *fn_span)
                    {
                        self.decorations.remove(i);
                        continue;
                    }
                    i += 1;
                }
                self.decorations.push(Deco {
                    kind: DecoKind::Call,
                    local: *destination_local,
                    range: *fn_span,
                    hover_text: "function call".to_string(),
                    overlapped: false,
                });
            }
        }
    }
}
