#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DecoKind {
    Lifetime,
    ImmBorrow,
    MutBorrow,
    Move,
    Call,
    SharedMut,
    Outlive,
}

impl DecoKind {
    fn order(self) -> u8 {
        match self {
            DecoKind::Lifetime => 0,
            DecoKind::ImmBorrow => 1,
            DecoKind::MutBorrow => 2,
            DecoKind::Move => 3,
            DecoKind::Call => 4,
            DecoKind::SharedMut => 5,
            DecoKind::Outlive => 6,
        }
    }
    fn name(self) -> &'static str {
        match self {
            DecoKind::Lifetime => "lifetime",
            DecoKind::ImmBorrow => "imm_borrow",
            DecoKind::MutBorrow => "mut_borrow",
            DecoKind::Move => "move",
            DecoKind::Call => "call",
            DecoKind::SharedMut => "shared_mut",
            DecoKind::Outlive => "outlive",
        }
    }
}

#[derive(Clone, Debug)]
pub struct Deco {
    pub kind: DecoKind,
    pub local: FnLocal,
    pub range: Range,
    pub hover_text: String,
    pub overlapped: bool,
}

impl Deco {
    pub fn to_lsp_value(&self, text: &str) -> Value {
        let start = utils::index_to_line_char(text, self.range.from());
        let end = utils::index_to_line_char(text, self.range.until());
        json!({
            "type": self.kind.name(),
            "local": {"id": self.local.id, "fn_id": self.local.fn_id},
            "range": {
                "start": {"line": start.0, "character": start.1},
                "end": {"line": end.0, "character": end.1},
            },
            "hover_text": self.hover_text,
            "overlapped": self.overlapped,
        })
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SelectReason {
    Var,
    Move,
    Borrow,
    Call,
}

pub struct SelectLocal {
    pos: Loc,
    candidate_local_decls: Vec<FnLocal>,
    selected: Option<(SelectReason, FnLocal, Range)>,
}

impl SelectLocal {
    pub fn new(pos: Loc) -> Self {
        Self {
            pos,
            candidate_local_decls: Vec::new(),
            selected: None,
        }
    }

    fn select(&mut self, reason: SelectReason, local: FnLocal, range: Range) {
        if !self.candidate_local_decls.contains(&local) {
            return;
        }
        if range.from() <= self.pos && self.pos <= range.until() {
            if let Some((old_reason, _, old_range)) = self.selected {
                match (old_reason, reason) {
                    (_, SelectReason::Var) => {
                        if range.size() < old_range.size() {
                            self.selected = Some((reason, local, range));
                        }
                    }
                    (SelectReason::Var, _) => {}
                    (_, SelectReason::Move) | (_, SelectReason::Borrow) => {
                        if range.size() < old_range.size() {
                            self.selected = Some((reason, local, range));
                        }
                    }
                    (SelectReason::Call, SelectReason::Call) => {
                        if old_range.size() < range.size() {
                            self.selected = Some((reason, local, range));
                        }
                    }
                    _ => {}
                }
            } else {
                self.selected = Some((reason, local, range));
            }
        }
    }

    pub fn selected(&self) -> Option<FnLocal> {
        self.selected.map(|v| v.1)
    }
}

impl MirVisitor for SelectLocal {
    fn visit_decl(&mut self, decl: &MirDecl) {
        let local = match decl {
            MirDecl::User { local, .. } => *local,
            MirDecl::Other { local, .. } => *local,
        };
        self.candidate_local_decls.push(local);
        if let MirDecl::User { local, span, .. } = decl {
            self.select(SelectReason::Var, *local, *span);
        }
    }
    fn visit_stmt(&mut self, stmt: &MirStatement) {
        if let MirStatement::Assign { rval, .. } = stmt {
            match rval {
                Some(MirRval::Move {
                    target_local,
                    range,
                }) => self.select(SelectReason::Move, *target_local, *range),
                Some(MirRval::Borrow {
                    target_local,
                    range,
                    ..
                }) => self.select(SelectReason::Borrow, *target_local, *range),
                _ => {}
            }
        }
    }
    fn visit_term(&mut self, term: &MirTerminator) {
        if let MirTerminator::Call {
            destination_local,
            fn_span,
        } = term
        {
            self.select(SelectReason::Call, *destination_local, *fn_span);
        }
    }
}

