//! Locating, installing and removing the Rust toolchain used for analysis.

use crate::{log_debug, log_error, log_info, log_trace, log_warn};
use std::path::{Path, PathBuf};
use std::process::Command;

const TARGET: &str = "rustowl::toolchain";

pub const HOST_TUPLE: &str = "x86_64-unknown-linux-gnu";
pub const TOOLCHAIN_CHANNEL: &str = "nightly";
pub const TOOLCHAIN_DATE: &str = "2025-06-20";
pub const VERSION: &str = "1.0.0-rc.1";

pub fn toolchain() -> String {
    format!("{TOOLCHAIN_CHANNEL}-{TOOLCHAIN_DATE}-{HOST_TUPLE}")
}

#[allow(deprecated)]
pub fn fallback_runtime_dir() -> PathBuf {
    let home = std::env::home_dir().unwrap_or_else(|| PathBuf::from("/"));
    home.join(".rustowl")
}

pub fn exe_dir() -> Option<PathBuf> {
    std::env::current_exe()
        .ok()
        .and_then(|p| p.parent().map(|p| p.to_path_buf()))
}

pub fn sysroot_from_runtime(runtime: impl AsRef<Path>) -> PathBuf {
    runtime.as_ref().join("sysroot").join(toolchain())
}

fn runtime_dirs() -> Vec<PathBuf> {
    let mut candidates = Vec::new();
    if let Some(dir) = exe_dir() {
        candidates.push(dir);
    }
    candidates.push(fallback_runtime_dir());
    candidates
        .into_iter()
        .filter(|p| sysroot_from_runtime(p).is_dir())
        .collect()
}

pub fn find_sysroot() -> Option<PathBuf> {
    runtime_dirs().first().map(sysroot_from_runtime)
}

/// Returns the sysroot, installing the toolchain when it cannot be found.
/// Exits the process when the installation fails.
pub fn get_sysroot() -> PathBuf {
    if let Some(sysroot) = find_sysroot() {
        return sysroot;
    }
    log_info!(TARGET, "sysroot not found; start setup toolchain");
    let fallback = fallback_runtime_dir();
    if let Err(e) = setup_toolchain(&fallback, false) {
        log_error!(TARGET, "{e:?}");
        std::process::exit(1);
    }
    sysroot_from_runtime(&fallback)
}

fn select_binary(sysroot: &Path, name: &str) -> String {
    let in_sysroot = sysroot.join("bin").join(name);
    if in_sysroot.is_file() {
        log_info!(TARGET, "{name} is selected in sysroot/bin");
        return in_sysroot.to_string_lossy().to_string();
    }
    if let Some(dir) = exe_dir() {
        let candidate = dir.join(name);
        if candidate.is_file() {
            log_info!(
                TARGET,
                "{name} is selected in the same directory as rustowl executable"
            );
            return candidate.to_string_lossy().to_string();
        }
    }
    log_warn!(TARGET, "{name} not found; fallback");
    name.to_string()
}

pub fn get_rustowlc_path(sysroot: &Path) -> String {
    select_binary(sysroot, "rustowlc")
}

pub fn set_rustc_env(command: &mut Command, sysroot: &Path) {
    command
        .env(
            "CARGO_ENCODED_RUSTFLAGS",
            format!("--sysroot={}", sysroot.display()),
        )
        .env("RUSTC_BOOTSTRAP", "1");
    let lib = sysroot.join("lib");
    let existing = std::env::var("LD_LIBRARY_PATH").unwrap_or_default();
    command.env(
        "LD_LIBRARY_PATH",
        format!("{}:{}", lib.display(), existing),
    );
}

/// Build a `cargo` command configured to use the RustOwl toolchain.
pub fn setup_cargo_command() -> Command {
    let sysroot = get_sysroot();
    let cargo = select_binary(&sysroot, "cargo");
    let rustowlc = select_binary(&sysroot, "rustowlc");
    let mut command = Command::new(cargo);
    command
        .env("RUSTC", &rustowlc)
        .env("RUSTC_WORKSPACE_WRAPPER", &rustowlc);
    set_rustc_env(&mut command, &sysroot);
    command
}

// ---------------------------------------------------------------------------
// installation

fn random_alnum(n: usize) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let bytes = crate::rand::random_bytes(n * 2);
    bytes
        .chunks(2)
        .map(|c| {
            let v = ((c[0] as usize) << 8) | c[1] as usize;
            CHARS[v % CHARS.len()] as char
        })
        .collect()
}

struct TempDir(PathBuf);

impl TempDir {
    fn new() -> Option<TempDir> {
        let base = std::env::temp_dir();
        for _ in 0..16 {
            let path = base.join(format!(".tmp{}", random_alnum(6)));
            match std::fs::create_dir(&path) {
                Ok(()) => return Some(TempDir(path)),
                Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => continue,
                Err(_) => return None,
            }
        }
        None
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn host_of(url: &str) -> (String, String) {
    let rest = url.split_once("://").map(|v| v.1).unwrap_or(url);
    let host = rest.split('/').next().unwrap_or("").to_string();
    let scheme = url.split_once("://").map(|v| v.0).unwrap_or("https");
    (host, format!("{scheme}://{}/", rest.split('/').next().unwrap_or("")))
}

fn download(url: &str, dest_file: &Path) -> Result<(), ()> {
    log_info!(TARGET, "start downloading {url}...");
    let (host, base) = host_of(url);
    log_debug!("reqwest::connect", "starting new connection: {base}");
    use std::net::ToSocketAddrs;
    if let Err(e) = (host.as_str(), 443).to_socket_addrs() {
        log_trace!("reqwest::retry", "shouldn't retry!");
        log_error!(TARGET, "failed to download tarball");
        log_error!(
            TARGET,
            "reqwest::Error {{ kind: Request, url: \"{url}\", source: hyper_util::client::legacy::Error(Connect, ConnectError(\"dns error\", {e:?})) }}"
        );
        return Err(());
    }
    let status = Command::new("curl")
        .args(["-fsSL", "-o"])
        .arg(dest_file)
        .arg(url)
        .stdin(std::process::Stdio::null())
        .status();
    match status {
        Ok(s) if s.success() => {
            log_info!(TARGET, "download finished");
            Ok(())
        }
        _ => {
            log_error!(TARGET, "failed to download tarball");
            Err(())
        }
    }
}

fn download_tarball_and_extract(url: &str, dest: &Path) -> Result<(), ()> {
    let archive = dest.join(".download.tar.gz");
    download(url, &archive)?;
    let status = Command::new("tar")
        .arg("-xzf")
        .arg(&archive)
        .arg("-C")
        .arg(dest)
        .status();
    let _ = std::fs::remove_file(&archive);
    match status {
        Ok(s) if s.success() => {
            log_info!(TARGET, "successfully unpacked");
            Ok(())
        }
        _ => {
            log_error!(TARGET, "failed to unpack tarball");
            Err(())
        }
    }
}

