//! Running the analysis driver for a workspace or a single file.

use crate::models::Workspace;
use crate::toolchain;
use crate::{log_info, log_warn};
use serde::Deserialize;
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::mpsc;

const TARGET: &str = "rustowl::lsp::analyze";

#[derive(Clone, Debug)]
pub struct Metadata {
    pub workspace_root: PathBuf,
    pub target_directory: PathBuf,
    pub packages_len: usize,
    pub root_package: Option<String>,
}

fn parse_metadata(data: &str) -> Option<Metadata> {
    let v: serde_json::Value = serde_json::from_str(data).ok()?;
    let obj = v.as_object()?;
    let packages = obj.get("packages")?.as_array()?;
    obj.get("workspace_members")?.as_array()?;
    let workspace_root = obj.get("workspace_root")?.as_str()?;
    let target_directory = obj.get("target_directory")?.as_str()?;
    obj.get("version")?.as_u64()?;
    let mut root_package = None;
    if let Some(root) = obj
        .get("resolve")
        .and_then(|r| r.as_object())
        .and_then(|r| r.get("root"))
        .and_then(|r| r.as_str())
    {
        for p in packages {
            if p.get("id").and_then(|v| v.as_str()) == Some(root) {
                root_package = p.get("name").and_then(|v| v.as_str()).map(|v| v.to_string());
            }
        }
    }
    Some(Metadata {
        workspace_root: PathBuf::from(workspace_root),
        target_directory: PathBuf::from(target_directory),
        packages_len: packages.len(),
        root_package,
    })
}

#[derive(Clone, Debug)]
pub struct Analyzer {
    path: PathBuf,
    metadata: Option<Metadata>,
}

pub enum AnalyzerEvent {
    CrateChecked { package: String, package_count: usize },
    Analyzed(Workspace),
}

#[derive(Deserialize)]
#[serde(tag = "reason", rename_all = "kebab-case")]
enum CargoCheckMessage {
    CompilerArtifact { target: CargoCheckMessageTarget },
}

#[derive(Deserialize)]
struct CargoCheckMessageTarget {
    name: String,
}

pub struct AnalyzeProcess {
    pub child: Option<Child>,
    pub events: mpsc::Receiver<AnalyzerEvent>,
}

impl AnalyzeProcess {
    pub fn kill(&mut self) {
        if let Some(mut child) = self.child.take() {
            let _ = child.kill();
            std::thread::spawn(move || {
                let _ = child.wait();
            });
        }
    }
}

impl Drop for AnalyzeProcess {
    fn drop(&mut self) {
        self.kill();
    }
}

impl Analyzer {
    pub fn new(path: &Path) -> Result<Analyzer, ()> {
        let path = path.to_path_buf();
        let mut cmd = toolchain::setup_cargo_command();
        let dir = if path.is_file() {
            path.parent().map(|p| p.to_path_buf()).unwrap_or_default()
        } else {
            path.clone()
        };
        cmd.args(["metadata", "--filter-platform", toolchain::HOST_TUPLE])
            .current_dir(&dir)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::null());
        let metadata = match cmd.spawn() {
            Ok(child) => match child.wait_with_output() {
                Ok(output) => parse_metadata(&String::from_utf8_lossy(&output.stdout)),
                Err(_) => None,
            },
            Err(_) => None,
        };
        if let Some(metadata) = metadata {
            Ok(Analyzer {
                path: metadata.workspace_root.clone(),
                metadata: Some(metadata),
            })
        } else if path.is_file() && path.extension().map(|v| v == "rs").unwrap_or(false) {
            Ok(Analyzer {
                path,
                metadata: None,
            })
        } else {
            log_warn!(TARGET, "Invalid analysis target: {}", path.display());
            Err(())
        }
    }

    pub fn target_path(&self) -> &Path {
        &self.path
    }

    /// Start the analysis. Panics (like the original) when the analysis
    /// process cannot be spawned; this is reported via `Err`.
    pub fn analyze(&self, all_targets: bool, all_features: bool) -> Result<AnalyzeProcess, String> {
        let root_package = self
            .metadata
            .as_ref()
            .and_then(|m| m.root_package.clone().map(|p| (m, p)));
        if let Some((metadata, package_name)) = root_package {
            self.analyze_package(metadata, &package_name, all_targets, all_features)
        } else {
            self.analyze_single_file()
        }
    }

    fn analyze_package(
        &self,
        metadata: &Metadata,
        package_name: &str,
        all_targets: bool,
        all_features: bool,
    ) -> Result<AnalyzeProcess, String> {
        let target_dir = metadata.target_directory.join("owl");
        log_info!(TARGET, "clear cargo cache");
        let mut clean = toolchain::setup_cargo_command();
        clean
            .args(["clean", "--package", package_name])
            .env("CARGO_TARGET_DIR", &target_dir)
            .current_dir(&self.path)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        if let Ok(mut child) = clean.spawn() {
            let _ = child.wait();
        }

        let mut command = toolchain::setup_cargo_command();
        let mut args = vec!["check", "--workspace"];
        if all_targets {
            args.push("--all-targets");
        }
        if all_features {
            args.push("--all-features");
        }
        args.extend_from_slice(&["--keep-going", "--message-format=json"]);
        command
            .args(args)
            .env("CARGO_TARGET_DIR", &target_dir)
            .env_remove("RUSTC_WRAPPER")
            .current_dir(&self.path)
            .stdin(Stdio::null())
            .stdout(Stdio::piped());
        if cache_enabled() {
            command.env("RUSTOWL_CACHE_DIR", target_dir.join("cache"));
        }
        if !crate::log::enabled(crate::log::Level::Info) {
            command.stderr(Stdio::null());
        }
        let package_count = metadata.packages_len;
        log_info!(TARGET, "start analyzing package {package_name}");
        let child = command.spawn().map_err(|e| {
            format!(
                "/workspace/src/lsp/analyze.rs:180:41|called `Result::unwrap()` on an `Err` value: {e:?}"
            )
        })?;
        Ok(spawn_reader(child, package_count))
    }

    fn analyze_single_file(&self) -> Result<AnalyzeProcess, String> {
        let sysroot = toolchain::get_sysroot();
        let rustowlc = toolchain::get_rustowlc_path(&sysroot);
        let mut command = Command::new(&rustowlc);
        command
            .arg(&rustowlc)
            .arg(format!("--sysroot={}", sysroot.display()))
            .arg("--crate-type=lib")
            .arg("-o/dev/null")
            .arg(&self.path)
            .stdin(Stdio::null())
            .stdout(Stdio::piped());
        toolchain::set_rustc_env(&mut command, &sysroot);
        if !crate::log::enabled(crate::log::Level::Info) {
            command.stderr(Stdio::null());
        }
        log_info!(TARGET, "start analyzing {}", self.path.display());
        let child = command.spawn().map_err(|e| {
            format!(
                "/workspace/src/lsp/analyze.rs:222:41|called `Result::unwrap()` on an `Err` value: {e:?}"
            )
        })?;
        Ok(spawn_reader(child, 0))
    }
}

fn cache_enabled() -> bool {
    match std::env::var("RUSTOWL_CACHE") {
        Ok(v) => !(v == "false" || v == "0"),
        Err(_) => true,
    }
}

fn spawn_reader(mut child: Child, package_count: usize) -> AnalyzeProcess {
    let stdout = child.stdout.take();
    let (tx, rx) = mpsc::channel();
    std::thread::spawn(move || {
