/// Describe a JSON value the way serde's `Unexpected` does.
pub fn unexpected(v: &Value) -> String {
    match v {
        Value::Null => "null".to_string(),
        Value::Bool(b) => format!("boolean `{b}`"),
        Value::Number(n) => {
            if n.is_f64() {
                let f = n.as_f64().unwrap_or(0.0);
                let mut s = format!("{f}");
                if f.is_finite() && !s.contains('.') && !s.contains('e') && !s.contains("inf") && !s.contains("NaN") {
                    s.push_str(".0");
                }
                format!("floating point `{s}`")
            } else {
                format!("integer `{n}`")
            }
        }
        Value::String(s) => format!("string {s:?}"),
        Value::Array(_) => "sequence".to_string(),
        Value::Object(_) => "map".to_string(),
    }
}

#[allow(dead_code)]
pub fn invalid_struct(v: &Value, name: &str) -> String {
    de::Error::invalid_type(de::Unexpected::Other(&unexpected(v)), &format!("struct {name}").as_str())
        .to_string_lossy()
}

trait ToStringLossy {
    fn to_string_lossy(&self) -> String;
}

impl ToStringLossy for serde_json::Error {
    fn to_string_lossy(&self) -> String {
        self.to_string()
    }
}
