        Value::Number(n) => {
            if n.is_f64() {
                let f = n.as_f64().unwrap_or(0.0);
                let mut s = format!("{f}");
                if f.is_finite() && !s.contains('.') && !s.contains('e') && !s.contains("inf") && !s.contains("NaN") {
