//! Output channel shared by the server and the backend.

use crate::jsonrpc::{self, Id, Outcome};
use serde_json::Value;
use std::collections::HashMap;
use std::io::Write;
use std::sync::atomic::{AtomicBool, AtomicI64, Ordering};
use std::sync::{mpsc, Mutex};

pub struct Client {
    out: Mutex<()>,
    next_id: AtomicI64,
    waiting: Mutex<HashMap<Id, mpsc::Sender<Outcome>>>,
    closed: AtomicBool,
}

impl Client {
    pub fn new() -> Self {
        Client {
            out: Mutex::new(()),
            next_id: AtomicI64::new(0),
            waiting: Mutex::new(HashMap::new()),
            closed: AtomicBool::new(false),
        }
    }

    pub fn write_body(&self, body: &str) {
        let _guard = self.out.lock().unwrap();
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = write!(lock, "Content-Length: {}\r\n\r\n{}", body.len(), body);
        let _ = lock.flush();
    }

    pub fn respond(&self, id: &Id, outcome: &Outcome) {
        self.write_body(&jsonrpc::response_body(id, outcome));
    }

    pub fn close(&self) {
        self.closed.store(true, Ordering::SeqCst);
    }

    pub fn is_closed(&self) -> bool {
        self.closed.load(Ordering::SeqCst)
    }

    /// Send a request to the client and block until the response arrives.
    pub fn send_request(&self, method: &str, params: Value) -> Option<Outcome> {
        if self.is_closed() {
            return None;
        }
