                *status = Status::Finished;
            }
        });
    }

    fn run_analysis(&self, analyzer: Analyzer, token: Arc<ProcessToken>, all_targets: bool, all_features: bool) {
        let mut progress = None;
        if self.work_done_progress.load(Ordering::SeqCst) {
            if let Some(client) = &self.client {
                progress = Some(ProgressToken::begin(client.clone()));
            }
        }
        let process = match analyzer.analyze(all_targets, all_features) {
            Ok(p) => p,
            Err(msg) => {
                let (loc, text) = msg.split_once('|').unwrap_or(("", &msg));
                crate::log::panic_message("tokio-runtime-worker", loc, text);
                return;
            }
        };
        let events = {
            let mut process = process;
            let events = std::mem::replace(&mut process.events, std::sync::mpsc::channel().1);
            *token.child.lock().unwrap() = Some(process);
            events
        };
        if token.cancelled.load(Ordering::SeqCst) {
            if let Some(mut p) = token.child.lock().unwrap().take() {
                p.kill();
            }
        }
        let mut analyzed_count: u64 = 0;
        loop {
            if token.cancelled.load(Ordering::SeqCst) {
                break;
            }
            let event = match events.recv_timeout(Duration::from_millis(20)) {
                Ok(e) => e,
                Err(std::sync::mpsc::RecvTimeoutError::Timeout) => continue,
                Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => break,
            };
            if token.cancelled.load(Ordering::SeqCst) {
                break;
            }
            match event {
                AnalyzerEvent::CrateChecked {
                    package,
                    package_count,
                } => {
                    analyzed_count += 1;
                    if let Some(p) = &progress {
                        let pc = package_count.max(1) as u64;
                        let percentage = (analyzed_count * 100 / pc).min(100);
                        p.report(format!("{package} analyzed"), percentage);
                    }
                }
                AnalyzerEvent::Analyzed(ws) => {
                    let mut analyzed = self.analyzed.lock().unwrap();
                    for krate in ws.0.into_values() {
                        if let Some(existing) = analyzed.as_mut() {
                            existing.merge(krate);
                        } else {
                            *analyzed = Some(krate);
                        }
                    }
                }
            }
        }
        if let Some(mut p) = token.child.lock().unwrap().take() {
            p.kill();
        }
        if let Some(p) = progress {
            p.finish();
        }
    }

