    // LSP handlers

    pub fn initialize(self: &Arc<Self>, params: InitializeParams, cancel: &Cancel) -> Value {
        let mut workspaces: Vec<PathBuf> = Vec::new();
        if let Some(root) = &params.root_uri {
            if let Ok(p) = root.to_file_path() {
                workspaces.push(p);
            }
        }
        if let Some(folders) = &params.workspace_folders {
            for f in folders {
                if let Ok(p) = f.uri.to_file_path() {
                    workspaces.push(p);
                }
            }
        }
        for path in workspaces {
            if cancel.is_cancelled() {
                return Value::Null;
            }
            self.add_analyze_target(&path);
        }
        if params
            .capabilities
            .window
            .as_ref()
            .and_then(|w| w.work_done_progress)
            .unwrap_or(false)
        {
            self.work_done_progress.store(true, Ordering::SeqCst);
        }
        self.do_analyze(cancel);
        if let Some(pid) = params.process_id {
            std::thread::spawn(move || loop {
                std::thread::sleep(Duration::from_secs(30));
                if !process_alive(pid) {
                    crate::log::panic_message(
                        "tokio-runtime-worker",
                        "/workspace/src/lsp/backend.rs:406:25",
