                self.do_analyze(&Cancel::none());
            }
        }
    }

    pub fn did_change(self: &Arc<Self>) {
        *self.analyzed.lock().unwrap() = None;
        self.shutdown_subprocesses();
    }

    pub fn did_change_workspace_folders(self: &Arc<Self>, added: Vec<PathBuf>) {
        for path in added {
            if self.add_analyze_target(&path) {
                self.do_analyze(&Cancel::none());
            }
        }
    }

