    }

    fn decos(&self, filepath: &Path, position: Loc) -> Result<Vec<Deco>, Status> {
        let mut selected = SelectLocal::new(position);
        let mut error = Status::Error;
        let analyzed = self.analyzed.lock().unwrap();
        if let Some(analyzed) = &*analyzed {
            for (filename, file) in analyzed.0.iter() {
                if filepath == PathBuf::from(filename) {
                    if !file.items.is_empty() {
                        error = Status::Finished;
                    }
                    for item in &file.items {
                        utils::mir_visit(item, &mut selected);
                    }
                }
            }
            let mut calc = CalcDecos::new(selected.selected());
            for (filename, file) in analyzed.0.iter() {
                if filepath == PathBuf::from(filename) {
                    for item in &file.items {
                        utils::mir_visit(item, &mut calc);
                    }
                }
            }
            calc.handle_overlapping();
            let decos = calc.decorations();
            if !decos.is_empty() {
                Ok(decos)
            } else {
                Err(error)
            }
        } else {
            Err(error)
        }
    }

    pub fn cursor(&self, params: CursorRequest) -> Value {
        let is_analyzed = self.analyzed.lock().unwrap().is_some();
        let status = *self.status.lock().unwrap();
        if let Ok(path) = params.document.uri.to_file_path() {
            if let Ok(text) = std::fs::read_to_string(&path) {
                let position = params.position;
                let pos = Loc(utils::line_char_to_index(
                    &text,
                    position.line,
                    position.character,
                ));
                let (decos, status) = match self.decos(&path, pos) {
                    Ok(v) => (v, status),
                    Err(e) => (
                        Vec::new(),
                        if status == Status::Finished { e } else { status },
                    ),
                };
                let decorations: Vec<Value> = decos.iter().map(|d| d.to_lsp_value(&text)).collect();
                return json!({
                    "is_analyzed": is_analyzed,
                    "status": status.name(),
                    "path": path.to_string_lossy(),
                    "decorations": decorations,
                });
            }
        }
        json!({
            "is_analyzed": is_analyzed,
            "status": status.name(),
            "path": Value::Null,
            "decorations": [],
        })
    }

    // ---------------------------------------------------------------------
    // check command

    pub fn check(path: &Path, all_targets: bool, all_features: bool) -> bool {
        let backend = Backend::new(None);
        if backend.add_analyze_target(path) {
            backend.analyze_with_options(all_targets, all_features, &Cancel::none());
            backend.wait_all_tasks();
            let analyzed = backend.analyzed.lock().unwrap();
            analyzed.as_ref().map(|v| !v.0.is_empty()).unwrap_or(false)
        } else {
            false
        }
    }
}

fn process_alive(pid: u32) -> bool {
    Path::new(&format!("/proc/{pid}")).exists()
}
