#[derive(PartialEq, Eq)]
enum TaskPhase {
    NotStarted,
    Running,
    Done,
}

struct Task {
    id: Id,
    phase: Mutex<TaskPhase>,
    cancel: Cancel,
    is_initialize: bool,
}

type ImmediateFn = Box<dyn FnOnce() -> Outcome + Send>;
type DeferredFn = Box<dyn FnOnce(&Cancel) -> Outcome + Send>;
type NotifyFn = Box<dyn FnOnce() + Send>;

enum Work {
    Immediate(ImmediateFn),
    Deferred(DeferredFn),
}

enum Fut {
    Ready(Option<(Id, Outcome)>),
    Tracked(Arc<Task>, Work),
    Notify(NotifyFn),
}

struct Shared {
    state: Mutex<State>,
    pending: Mutex<HashMap<Id, Arc<Task>>>,
    client: Arc<Client>,
    backend: Arc<Backend>,
    handlers: Mutex<Vec<JoinHandle<()>>>,
}

impl Shared {
    fn complete(&self, task: &Arc<Task>, outcome: Outcome) {
        {
            let mut phase = task.phase.lock().unwrap();
            if *phase == TaskPhase::Done {
                return;
            }
            *phase = TaskPhase::Done;
        }
        {
            let mut pending = self.pending.lock().unwrap();
            if let Some(t) = pending.get(&task.id) {
                if Arc::ptr_eq(t, task) {
                    pending.remove(&task.id);
                }
            }
        }
        let ok = outcome.is_ok();
        self.client.respond(&task.id, &outcome);
        if task.is_initialize {
            *self.state.lock().unwrap() = if ok {
                State::Initialized
            } else {
                State::Uninitialized
            };
        }
    }

    fn cancel_task(&self, task: &Arc<Task>) {
        task.cancel.0.store(true, Ordering::SeqCst);
        let running = *task.phase.lock().unwrap() == TaskPhase::Running;
        if running {
            self.complete(task, Err(ErrorObj::request_cancelled()));
        }
    }

    fn cancel(&self, id: &Id) {
        let task = self.pending.lock().unwrap().get(id).cloned();
        if let Some(task) = task {
            self.cancel_task(&task);
        }
    }

    fn cancel_all(&self) {
        let tasks: Vec<Arc<Task>> = self.pending.lock().unwrap().values().cloned().collect();
        for t in tasks {
            self.cancel_task(&t);
        }
    }

    fn spawn_handler(&self, f: impl FnOnce() + Send + 'static) {
        let h = std::thread::spawn(f);
        self.handlers.lock().unwrap().push(h);
    }
}

