fn route(method: &str) -> Option<(Kind, Layer)> {
    match method {
        "initialize" => Some((Kind::Request, Layer::Initialize)),
        "shutdown" => Some((Kind::Request, Layer::Shutdown)),
        "exit" => Some((Kind::Notification, Layer::Exit)),
        "$/cancelRequest" => Some((Kind::Notification, Layer::Cancel)),
        "rustowl/cursor" | "rustowl/analyze" => Some((Kind::Request, Layer::Normal)),
        m if NOTIFICATIONS.contains(&m) => Some((Kind::Notification, Layer::Normal)),
        m if OTHER_REQUESTS.iter().any(|(n, _, _)| *n == m) => Some((Kind::Request, Layer::Normal)),
        _ => None,
    }
}

fn parse_params<P: DeserializeOwned>(params: Option<Value>) -> Result<P, ErrorObj> {
    match params {
        Some(p) => serde_json::from_value(p).map_err(|e| ErrorObj::invalid_params(e.to_string())),
        None => Err(ErrorObj::invalid_params("Missing params field")),
    }
}

fn parse_no_params(params: &Option<Value>) -> Result<(), ErrorObj> {
    match params {
        Some(p) => Err(ErrorObj::invalid_params(format!("Unexpected params: {p}"))),
        None => Ok(()),
    }
}

fn validate_other(params: &Option<Value>, field: &str, name: &str) -> Result<(), ErrorObj> {
    match params {
        None => Err(ErrorObj::invalid_params("Missing params field")),
        Some(Value::Object(o)) => {
            if o.contains_key(field) {
                Ok(())
            } else {
                Err(ErrorObj::invalid_params(format!("missing field `{field}`")))
            }
        }
        Some(Value::Array(_)) => Err(ErrorObj::invalid_params(format!(
            "invalid type: sequence, expected struct {name}"
        ))),
        Some(v) => Err(ErrorObj::invalid_params(invalid_struct(v, name))),
    }
}

pub struct Server {
    shared: Arc<Shared>,
}

impl Server {
    pub fn new() -> Self {
        let client = Arc::new(Client::new());
        let backend = Backend::new(Some(client.clone()));
        Server {
            shared: Arc::new(Shared {
                state: Mutex::new(State::Uninitialized),
                pending: Mutex::new(HashMap::new()),
                client,
                backend,
                handlers: Mutex::new(Vec::new()),
            }),
        }
    }

    fn not_initialized(&self, id: Option<Id>, state: State) -> Fut {
        let err = match state {
            State::Uninitialized => ErrorObj::not_initialized(),
            _ => ErrorObj::invalid_request(),
        };
        Fut::Ready(id.map(|id| (id, Err(err))))
    }

    /// Register a tracked (cancellable) request. Returns `None` when the id
    /// is already in use, in which case an "Invalid request" is produced.
    fn track(&self, id: Id, work: Work, is_initialize: bool) -> Fut {
        let mut pending = self.shared.pending.lock().unwrap();
        if pending.contains_key(&id) {
            return Fut::Ready(Some((id, Err(ErrorObj::invalid_request()))));
        }
        let task = Arc::new(Task {
            id: id.clone(),
            phase: Mutex::new(TaskPhase::NotStarted),
            cancel: Cancel::none(),
            is_initialize,
        });
        pending.insert(id, task.clone());
        Fut::Tracked(task, work)
    }

    fn call(&self, req: Request) -> Fut {
        let Request { method, params, id } = req;
        let (kind, layer) = match route(&method) {
            Some(r) => r,
            None => {
                if method.starts_with("$/") {
                    return Fut::Ready(None);
                }
                let mut err = ErrorObj::method_not_found();
                err.data = Some(Value::String(method));
                return Fut::Ready(id.map(|id| (id, Err(err))));
            }
        };
        let state = *self.shared.state.lock().unwrap();
        match layer {
            Layer::Cancel => {
                if let Some(id) = id {
                    return Fut::Ready(Some((id, Err(ErrorObj::invalid_request()))));
                }
                if let Ok(p) = parse_params::<CancelParams>(params) {
                    let id = match p.id {
                        NumberOrString::Number(n) => Id::Number(n as i64),
                        NumberOrString::String(s) => Id::String(s),
                    };
                    self.shared.cancel(&id);
                }
                Fut::Ready(None)
            }
            Layer::Exit => {
                *self.shared.state.lock().unwrap() = State::Exited;
                self.shared.cancel_all();
                self.shared.client.close();
                Fut::Ready(None)
            }
            Layer::Initialize => {
                if state != State::Uninitialized {
                    return Fut::Ready(id.map(|id| (id, Err(ErrorObj::invalid_request()))));
                }
                let id = match id {
                    Some(id) => id,
                    None => return Fut::Ready(None),
