    fn request_work(&self, method: &str, params: Option<Value>) -> Work {
        let backend = self.shared.backend.clone();
        match method {
            "rustowl/cursor" => match parse_params::<CursorRequest>(params) {
                Err(e) => Work::Immediate(Box::new(move || Err(e))),
                Ok(p) => Work::Immediate(Box::new(move || Ok(backend.cursor(p)))),
            },
            "rustowl/analyze" => match parse_params::<AnalyzeRequest>(params) {
                Err(e) => Work::Immediate(Box::new(move || Err(e))),
                Ok(_) => Work::Deferred(Box::new(move |cancel| Ok(backend.analyze_request(cancel)))),
            },
            m => {
