                    Err(e) => Work::Immediate(Box::new(move || Err(e))),
                    Ok(()) => Work::Immediate(Box::new(|| Err(ErrorObj::method_not_found()))),
                }
            }
        }
    }

    fn notification(&self, method: &str, params: Option<Value>) -> Fut {
        let backend = self.shared.backend.clone();
        match method {
            "initialized" => {
                let _ = parse_params::<InitializedParams>(params);
                Fut::Ready(None)
