                        let added = p
                            .event
                            .added
                            .iter()
                            .filter_map(|f| f.uri.to_file_path().ok())
                            .collect();
                        backend.did_change_workspace_folders(added);
                    })),
                    Err(_) => Fut::Ready(None),
                }
            }
            _ => Fut::Ready(None),
        }
    }

    fn flush(&self, batch: Vec<Fut>) {
        for fut in batch {
            match fut {
                Fut::Ready(Some((id, outcome))) => self.shared.client.respond(&id, &outcome),
