//! LSP server main loop: request routing, server state and cancellation.

use crate::backend::{Backend, Cancel};
use crate::client::Client;
use crate::jsonrpc::{self, DecodeError, ErrorObj, Id, Message, Outcome, Request};
use crate::lsp_types::*;
