fn route(method: &str) -> Option<(Kind, Layer)> {
    match method {
        "initialize" => Some((Kind::Request, Layer::Initialize)),
        "shutdown" => Some((Kind::Request, Layer::Shutdown)),
        "exit" => Some((Kind::Notification, Layer::Exit)),
        "$/cancelRequest" => Some((Kind::Notification, Layer::Cancel)),
        "rustowl/cursor" | "rustowl/analyze" => Some((Kind::Request, Layer::Normal)),
        m if NOTIFICATIONS.contains(&m) => Some((Kind::Notification, Layer::Normal)),
        m if OTHER_REQUESTS.iter().any(|(n, _, _)| *n == m) => Some((Kind::Request, Layer::Normal)),
        _ => None,
    }
}

fn parse_params<P: DeserializeOwned>(params: Option<Value>) -> Result<P, ErrorObj> {
    match params {
        Some(p) => serde_json::from_value(p).map_err(|e| ErrorObj::invalid_params(e.to_string())),
        None => Err(ErrorObj::invalid_params("Missing params field")),
    }
}

fn parse_no_params(params: &Option<Value>) -> Result<(), ErrorObj> {
    match params {
        Some(p) => Err(ErrorObj::invalid_params(format!("Unexpected params: {p}"))),
        None => Ok(()),
    }
}

fn validate_other(params: &Option<Value>, field: &str, name: &str) -> Result<(), ErrorObj> {
    match params {
        None => Err(ErrorObj::invalid_params("Missing params field")),
        Some(Value::Object(o)) => {
            if o.contains_key(field) {
                Ok(())
            } else {
                Err(ErrorObj::invalid_params(format!("missing field `{field}`")))
            }
        }
        Some(Value::Array(_)) => Err(ErrorObj::invalid_params(format!(
            "invalid type: sequence, expected struct {name}"
        ))),
        Some(v) => Err(ErrorObj::invalid_params(invalid_struct(v, name))),
    }
}

pub struct Server {
    shared: Arc<Shared>,
}

impl Server {
    pub fn new() -> Self {
        let client = Arc::new(Client::new());
        let backend = Backend::new(Some(client.clone()));
