fn expect_err(v: &Value, what: &str) -> String {
    format!("invalid type: {}, expected {}", unexpected(v), what)
}

fn check_int(v: &Value, ty: &str, min: i64, max: i64) -> Result<(), String> {
    match v {
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                if i < min || i > max {
                    return Err(format!("invalid value: integer `{i}`, expected {ty}"));
                }
                Ok(())
            } else if let Some(u) = n.as_u64() {
                Err(format!("invalid value: integer `{u}`, expected {ty}"))
            } else {
                Err(expect_err(v, ty))
            }
        }
        _ => Err(expect_err(v, ty)),
    }
}

pub fn check(v: &Value, ty: &T) -> Result<(), String> {
    match ty {
        T::Any => Ok(()),
        T::Opt(inner) => {
            if v.is_null() {
                Ok(())
            } else {
                check(v, inner)
            }
        }
        T::Str => match v {
            Value::String(_) => Ok(()),
            _ => Err(expect_err(v, "a string")),
        },
        T::Bool => match v {
            Value::Bool(_) => Ok(()),
            _ => Err(expect_err(v, "a boolean")),
        },
        T::U32 => check_int(v, "u32", 0, u32::MAX as i64),
        T::I32 => check_int(v, "i32", i32::MIN as i64, i32::MAX as i64),
        T::Url => match v {
            Value::String(s) => url::Url::parse(s)
                .map(|_| ())
                .map_err(|e| format!("{e}: {s:?}")),
            _ => Err(expect_err(v, "a string representing an URL")),
        },
        T::Vec(inner) => match v {
            Value::Array(items) => {
                for item in items {
                    check(item, inner)?;
                }
                Ok(())
            }
            _ => Err(expect_err(v, "a sequence")),
        },
        T::S(schema) => check_struct(v, schema),
    }
}

fn check_fields(map: &Map<String, Value>, schema: &Schema) -> Result<(), String> {
    for (k, val) in map.iter() {
        if let Some(f) = schema.fields.iter().find(|f| f.name == k) {
            check(val, &f.ty)?;
        }
    }
    for f in schema.fields {
        if !map.contains_key(f.name) && !matches!(f.ty, T::Opt(_) | T::Any) {
            return Err(format!("missing field `{}`", f.name));
        }
    }
    let rest: Map<String, Value> = map
        .iter()
        .filter(|(k, _)| !schema.fields.iter().any(|f| f.name == k.as_str()))
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    for fl in schema.flatten {
        check_fields(&rest, fl)?;
    }
    Ok(())
}

pub fn check_struct(v: &Value, schema: &Schema) -> Result<(), String> {
    match v {
        Value::Object(map) => check_fields(map, schema),
        Value::Array(items) if schema.flatten.is_empty() => {
            for (i, f) in schema.fields.iter().enumerate() {
                match items.get(i) {
                    Some(item) => check(item, &f.ty)?,
                    None => {
                        return Err(format!(
                            "invalid length {}, expected struct {} with {} element{}",
                            items.len(),
                            schema.name,
                            schema.fields.len(),
                            if schema.fields.len() == 1 { "" } else { "s" }
                        ))
                    }
                }
            }
            if items.len() > schema.fields.len() {
                return Err(format!(
                    "invalid length {}, expected fewer elements in array",
                    items.len()
                ));
            }
            Ok(())
        }
        _ => Err(expect_err(v, &format!("struct {}", schema.name))),
    }
}
